// Build a lemma's full paradigm from Whitaker's shared stem/suffix recipes.
//
// The recipes are generated by scripts/build-dictionary.mjs and loaded only
// when a reader opens a paradigm page. Each recipe is [stemKey, suffix, slot].

import { slotGroupLabel, slotLabel } from './grammar.js'

let cachedRules = null
let pendingRules = null

export function loadParadigmRules() {
  if (cachedRules) return Promise.resolve(cachedRules)
  if (!pendingRules) {
    pendingRules = import('../data/paradigm-rules.generated.js')
      .then((module) => {
        cachedRules = module.paradigmRules
        return cachedRules
      })
      .catch((error) => {
        pendingRules = null
        throw error
      })
  }
  return pendingRules
}

export function buildParadigm(lemma, rules) {
  if (!lemma?.sig || !lemma.stems?.length || !rules?.[lemma.sig]) return []
  const out = []
  const seen = new Set()

  for (const recipe of rules[lemma.sig]) {
    if (!Array.isArray(recipe) || recipe.length < 3) continue
    const [stemKey, suffix, slot] = recipe
    const stem = lemma.stems[stemKey - 1]
    if (!stem) continue
    const form = `${stem}${suffix}`
    if (!form || seen.has(slot)) continue
    seen.add(slot)
    out.push({ form, slot, label: slotLabel(slot) })
  }

  return out
}

const GROUP_ORDER = [
  'Noun',
  'Pronoun',
  'Adjective',
  'Numeral',
  'present active indicative',
  'present passive indicative',
  'imperfect active indicative',
  'imperfect passive indicative',
  'future active indicative',
  'future passive indicative',
  'perfect active indicative',
  'perfect passive indicative',
  'pluperfect active indicative',
  'pluperfect passive indicative',
  'future perfect active indicative',
  'future perfect passive indicative',
  'present active subjunctive',
  'present passive subjunctive',
  'imperfect active subjunctive',
  'imperfect passive subjunctive',
  'perfect active subjunctive',
  'perfect passive subjunctive',
  'pluperfect active subjunctive',
  'pluperfect passive subjunctive',
  'present active imperative',
  'present passive imperative',
  'future active imperative',
  'future passive imperative',
  'present active infinitive',
  'present passive infinitive',
  'perfect active infinitive',
  'perfect passive infinitive',
  'future active infinitive',
  'future passive infinitive',
  'perfect passive participle',
  'future active participle',
  'future passive participle',
  'present active participle',
  'Supine',
  'Adverb',
  'Preposition',
  'Conjunction',
  'Interjection',
]

function groupRank(title) {
  const index = GROUP_ORDER.indexOf(title)
  return index === -1 ? 999 : index
}

export function groupParadigm(entries) {
  const groups = new Map()
  for (const entry of entries) {
    const title = slotGroupLabel(entry.slot)
    if (!groups.has(title)) groups.set(title, [])
    groups.get(title).push(entry)
  }
  return [...groups.entries()]
    .map(([title, items]) => ({ title, items }))
    .sort((a, b) => groupRank(a.title) - groupRank(b.title))
}
